272	// array-layout: hand-built ArrayData from bytes (structure from the input, contents from a PRNG).
273	
274	const Input = struct {
275	    bytes: []const u8,
276	    pos: usize = 0,
277	
278	    fn byte(in: *Input) u8 {
279	        if (in.pos >= in.bytes.len) return 0;
280	        defer in.pos += 1;
281	        return in.bytes[in.pos];
282	    }
283	
284	    fn below(in: *Input, n: usize) usize {
285	        if (n == 0) return 0;
286	        return (@as(usize, in.byte()) | @as(usize, in.byte()) << 8) % n;
287	    }
288	};
289	
290	const int_types = [_]zarrow.IntType{
291	    .{ .bit_width = 8, .signed = true },  .{ .bit_width = 8, .signed = false },
292	    .{ .bit_width = 16, .signed = true }, .{ .bit_width = 16, .signed = false },
293	    .{ .bit_width = 32, .signed = true }, .{ .bit_width = 32, .signed = false },
294	    .{ .bit_width = 64, .signed = true }, .{ .bit_width = 64, .signed = false },
295	};
296	
297	fn intDataType(t: zarrow.IntType) DataType {
298	    return switch (t.bit_width) {
299	        8 => if (t.signed) .{ .int8 = {} } else .{ .uint8 = {} },
300	        16 => if (t.signed) .{ .int16 = {} } else .{ .uint16 = {} },
301	        32 => if (t.signed) .{ .int32 = {} } else .{ .uint32 = {} },
302	        else => if (t.signed) .{ .int64 = {} } else .{ .uint64 = {} },
303	    };
304	}
305	
306	fn genType(in: *Input, a: Allocator, depth: u32) Allocator.Error!*const DataType {
307	    const dt = try a.create(DataType);
308	    const unit: zarrow.TimeUnit = @enumFromInt(in.byte() % 4);
309	    const leaf_kinds = 30;
310	    const pick = in.byte() % @as(u8, if (depth >= 3) leaf_kinds else leaf_kinds + 12);
311	    dt.* = switch (pick) {
312	        0 => .{ .null = {} },
313	        1 => .{ .bool = {} },
314	        2...9 => intDataType(int_types[pick - 2]),
315	        10 => .{ .half_float = {} },
316	        11 => .{ .float = {} },
317	        12 => .{ .double = {} },
318	        13 => .{ .string = {} },
319	        14 => .{ .binary = {} },
320	        15 => .{ .large_string = {} },
321	        16 => .{ .large_binary = {} },
322	        17 => .{ .string_view = {} },
323	        18 => .{ .binary_view = {} },
324	        19 => .{ .fixed_size_binary = .{ .byte_width = @as(i32, in.byte() % 20) - 2 } },
325	        20 => .{ .date32 = {} },
326	        21 => .{ .date64 = {} },
327	        22 => .{ .timestamp = .{ .unit = unit, .timezone = null } },
328	        23 => .{ .time32 = .{ .unit = unit } },
329	        24 => .{ .time64 = .{ .unit = unit } },
330	        25 => .{ .duration = .{ .unit = unit } },
331	        26 => .{ .interval_month_day_nano = .{ .unit = .month_day_nano } },
332	        27 => .{ .decimal128 = .{ .precision = in.byte() % 40, .scale = in.byte() % 40 } },
333	        28 => .{ .decimal256 = .{ .precision = in.byte() % 80, .scale = in.byte() % 80 } },
334	        29 => .{ .decimal32 = .{ .precision = in.byte() % 12, .scale = in.byte() % 12 } },
335	        30 => .{ .list = .{ .value_field = try genField(in, a, depth) } },
336	        31 => .{ .large_list = .{ .value_field = try genField(in, a, depth) } },
337	        32 => .{ .list_view = .{ .value_field = try genField(in, a, depth) } },
338	        33 => .{ .large_list_view = .{ .value_field = try genField(in, a, depth) } },
339	        34 => .{ .fixed_size_list = .{ .value_field = try genField(in, a, depth), .list_size = @as(i32, in.byte() % 6) - 1 } },
340	        35 => .{ .struct_ = .{ .fields = try genFields(in, a, depth, in.byte() % 4) } },
341	        36, 37 => blk: {
342	            const fields = try genFields(in, a, depth, 1 + in.byte() % 3);
343	            const ids = try a.alloc(i8, fields.len);
344	            for (ids, 0..) |*id, i| id.* = if (in.byte() % 4 == 0) @bitCast(in.byte()) else @intCast(i);
345	            const u: zarrow.UnionType = .{ .type_ids = ids, .fields = fields, .mode = if (pick == 36) .sparse else .dense };
346	            break :blk if (pick == 36) .{ .sparse_union = u } else .{ .dense_union = u };
347	        },
348	        38 => .{ .dictionary = .{ .index_type = int_types[in.byte() % 8], .value_type = try genType(in, a, depth + 1) } },
349	        39 => .{ .map = .{ .key_field = try genField(in, a, depth), .item_field = try genField(in, a, depth) } },
350	        40 => .{ .run_end_encoded = .{ .run_end_type = int_types[in.byte() % 8], .value_type = try genType(in, a, depth + 1) } },
351	        else => .{ .extension = .{ .name = "fuzz.ext", .storage_type = try genType(in, a, depth + 1) } },
352	    };
353	    return dt;
354	}
355	
356	fn genField(in: *Input, a: Allocator, depth: u32) Allocator.Error!Field {
357	    return .{ .name = "f", .data_type = try genType(in, a, depth + 1), .nullable = in.byte() % 2 == 0 };
358	}
359	
360	fn genFields(in: *Input, a: Allocator, depth: u32, n: usize) Allocator.Error![]const Field {
361	    const fields = try a.alloc(Field, n);
362	    for (fields) |*f| f.* = try genField(in, a, depth);
363	    return fields;
364	}
