816	fn usage() noreturn {
817	    std.debug.print(
818	        \\usage: zarrow-fuzz <target> replay <file|dir>...
819	        \\       zarrow-fuzz <target> run <iters|secs s> --corpus <dir>... --out <dir> [--seed N] [--max-len N] [--alloc-cap N] [--timeout S]
820	        \\       zarrow-fuzz gen-seeds <corpus-root>
821	        \\targets: ipc-stream ipc-stream-zero-copy ipc-file array-layout compute c-abi
822	        \\
823	    , .{});
824	    std.process.exit(2);
825	}
