827	pub fn main(init: std.process.Init) !void {
828	    const gpa = init.gpa;
829	    const io = init.io;
830	    const arena = init.arena.allocator();
831	    const argv = try init.minimal.args.toSlice(arena);
832	    var args: std.ArrayList([]const u8) = .empty;
833	    var i: usize = 0;
834	    while (i < argv.len) : (i += 1) {
835	        if (std.mem.eql(u8, argv[i], "--timeout") and i + 1 < argv.len) {
836	            i += 1;
837	            hang_seconds = std.fmt.parseInt(u64, argv[i], 10) catch usage();
838	        } else try args.append(arena, argv[i]);
839	    }
840	    if (args.items.len < 3) usage();
841	    if (std.mem.eql(u8, args.items[1], "gen-seeds")) return genSeeds(gpa, io, args.items[2]);
842	    const target = std.meta.stringToEnum(Target, args.items[1]) orelse usage();
843	    (try std.Thread.spawn(.{}, watchdog, .{io})).detach();
844	    if (std.mem.eql(u8, args.items[2], "replay")) return replay(gpa, io, target, args.items[3..]);
845	    if (std.mem.eql(u8, args.items[2], "run")) return run(gpa, io, target, args.items[3..]);
846	    usage();
847	}
