849	/// Files directly under `path` (or `path` itself), sorted for a stable order.
850	fn listInputs(a: Allocator, io: std.Io, path: []const u8, out: *std.ArrayList([]const u8)) !void {
851	    var dir = std.Io.Dir.cwd().openDir(io, path, .{ .iterate = true }) catch |e| switch (e) {
852	        error.NotDir => return out.append(a, path),
853	        else => return e,
854	    };
855	    defer dir.close(io);
856	    const start = out.items.len;
857	    var it = dir.iterate();
858	    while (try it.next(io)) |entry| {
859	        if (entry.kind != .file) continue;
860	        if (std.mem.endsWith(u8, entry.name, ".md") or std.mem.eql(u8, entry.name, "NOTICE")) continue;
861	        try out.append(a, try std.fs.path.join(a, &.{ path, entry.name }));
862	    }
863	    std.mem.sort([]const u8, out.items[start..], {}, struct {
864	        fn lt(_: void, x: []const u8, y: []const u8) bool {
865	            return std.mem.order(u8, x, y) == .lt;
866	        }
867	    }.lt);
868	}
