870	fn replay(gpa: Allocator, io: std.Io, target: Target, paths: []const []const u8) !void {
871	    var arena_state = std.heap.ArenaAllocator.init(gpa);
872	    defer arena_state.deinit();
873	    const a = arena_state.allocator();
874	    var files: std.ArrayList([]const u8) = .empty;
875	    for (paths) |p| try listInputs(a, io, p, &files);
876	    var ok: usize = 0;
877	    var errors: usize = 0;
878	    explain = files.items.len == 1;
879	    for (files.items) |path| {
880	        const bytes = std.Io.Dir.cwd().readFileAlloc(io, path, gpa, .limited(max_input_len)) catch |e| {
881	            std.debug.print("skip {s}: {s}\n", .{ path, @errorName(e) });
882	            continue;
883	        };
884	        defer gpa.free(bytes);
885	        current_path = path;
886	        const fb = runOne(target, gpa, bytes);
887	        _ = progress.fetchAdd(1, .monotonic);
888	        current_path = "";
889	        if (fb.err != null) errors += 1 else ok += 1;
890	        if (files.items.len == 1) std.debug.print("{s}: {s}, {d} batches, validateFull: {s}\n", .{
891	            path,
892	            if (fb.err) |e| @errorName(e) else "ok",
893	            fb.batches,
894	            if (fb.invalid) |e| @errorName(e) else "ok",
895	        });
896	    }
897	    std.debug.print("{s}: replayed {d} inputs ({d} decoded, {d} rejected), no crash\n", .{ @tagName(target), files.items.len, ok, errors });
898	}
