900	fn run(gpa: Allocator, io: std.Io, target: Target, args: []const []const u8) !void {
901	    var arena_state = std.heap.ArenaAllocator.init(gpa);
902	    defer arena_state.deinit();
903	    const a = arena_state.allocator();
904	    if (args.len < 1) usage();
905	    const budget = args[0];
906	    const by_time = std.mem.endsWith(u8, budget, "s");
907	    const limit = std.fmt.parseInt(u64, if (by_time) budget[0 .. budget.len - 1] else budget, 10) catch usage();
908	    var out_dir: ?[]const u8 = null;
909	    var seed: u64 = @truncate(@as(u96, @bitCast(std.Io.Timestamp.now(io, .real).toNanoseconds())));
910	    var max_len: usize = 64 << 10;
911	    var corpus_paths: std.ArrayList([]const u8) = .empty;
912	    var i: usize = 1;
913	    while (i + 1 < args.len) : (i += 2) {
914	        const v = args[i + 1];
915	        if (std.mem.eql(u8, args[i], "--corpus")) {
916	            listInputs(a, io, v, &corpus_paths) catch |e| std.debug.print("corpus {s}: {s}\n", .{ v, @errorName(e) });
917	        } else if (std.mem.eql(u8, args[i], "--out")) {
918	            out_dir = v;
919	        } else if (std.mem.eql(u8, args[i], "--seed")) {
920	            seed = std.fmt.parseInt(u64, v, 10) catch usage();
921	        } else if (std.mem.eql(u8, args[i], "--max-len")) {
922	            max_len = @min(std.fmt.parseInt(usize, v, 10) catch usage(), max_input_len);
923	        } else if (std.mem.eql(u8, args[i], "--alloc-cap")) {
924	            alloc_cap = std.fmt.parseInt(usize, v, 10) catch usage();
925	        } else usage();
926	    }
927	    const out = out_dir orelse usage();
928	    const cwd = std.Io.Dir.cwd();
929	    const grow_dir = try std.fs.path.join(a, &.{ out, "corpus" });
930	    try cwd.createDirPath(io, grow_dir);
931	    try listInputs(a, io, grow_dir, &corpus_paths);
932	    const current = try cwd.createFile(io, try std.fs.path.join(a, &.{ out, "current.bin" }), .{ .truncate = true });
933	    defer current.close(io);
934	    var out_handle = try cwd.openDir(io, out, .{});
935	    defer out_handle.close(io);
936	
937	    // Load the corpus, skipping inputs that crashed before (tools/fuzz.py marks <out>/skip/<hash>).
938	    var corpus: std.ArrayList([]const u8) = .empty;
939	    var seen: std.AutoHashMapUnmanaged(u64, void) = .empty;
940	    for (corpus_paths.items) |path| {
941	        const bytes = cwd.readFileAlloc(io, path, a, .limited(max_len)) catch continue;
942	        const hex = hexName(bytes);
943	        const crash_name = try std.fmt.allocPrint(a, "skip/{s}", .{&hex});
944	        if (out_handle.statFile(io, crash_name, .{})) |_| {
945	            std.debug.print("skipping known crasher {s}\n", .{path});
946	            continue;
947	        } else |_| {}
948	        try current.writePositionalAll(io, bytes, 0);
949	        try current.setLength(io, bytes.len);
950	        const fb = runOne(target, gpa, bytes);
951	        _ = progress.fetchAdd(1, .monotonic);
952	        try seen.put(a, fb.sig(), {});
953	        try corpus.append(a, bytes);
954	    }
955	    if (corpus.items.len == 0) try corpus.append(a, "");
956	    std.debug.print("{s}: seed {d}, {d} corpus inputs, {d} signatures\n", .{ @tagName(target), seed, corpus.items.len, seen.count() });
957	
958	    var prng = std.Random.DefaultPrng.init(seed);
959	    const rng = prng.random();
960	    var buf: std.ArrayList(u8) = .empty;
961	    defer buf.deinit(gpa);
962	    const start = std.Io.Timestamp.now(io, .awake);
963	    var iters: u64 = 0;
964	    while (true) : (iters += 1) {
965	        if (iters % 256 == 0) {
966	            const elapsed: u64 = @intCast(start.durationTo(std.Io.Timestamp.now(io, .awake)).toSeconds());
967	            if ((by_time and elapsed >= limit) or (!by_time and iters >= limit)) break;
968	            if (iters % (1 << 14) == 0 and iters > 0)
969	                std.debug.print("#{d} {d}s corpus {d} signatures {d}\n", .{ iters, elapsed, corpus.items.len, seen.count() });
970	        } else if (!by_time and iters >= limit) break;
971	
972	        buf.clearRetainingCapacity();
973	        try buf.appendSlice(gpa, corpus.items[rng.uintLessThan(usize, corpus.items.len)]);
974	        try mutate(rng, gpa, &buf, corpus.items, max_len);
975	        try current.writePositionalAll(io, buf.items, 0);
976	        try current.setLength(io, buf.items.len);
977	        const fb = runOne(target, gpa, buf.items);
978	        _ = progress.fetchAdd(1, .monotonic);
979	        const gop = try seen.getOrPut(a, fb.sig());
980	        // ponytail: fixed corpus cap; signature-based growth has no coverage to prune with.
981	        if (gop.found_existing or corpus.items.len >= max_corpus) continue;
982	        const copy = try a.dupe(u8, buf.items);
983	        try corpus.append(a, copy);
984	        const hex = hexName(copy);
985	        const name = try std.fmt.allocPrint(a, "{s}.bin", .{&hex});
986	        var dir = try cwd.openDir(io, grow_dir, .{});
987	        defer dir.close(io);
988	        try dir.writeFile(io, .{ .sub_path = name, .data = copy });
989	    }
990	    std.debug.print("{s}: done, {d} execs, corpus {d}, {d} signatures\n", .{ @tagName(target), iters, corpus.items.len, seen.count() });
991	}
