1	//! zarrow fuzz harness: one executable, one `runOne` per target (see docs/fuzzing.md).
2	//!
3	//!   zarrow-fuzz <target> replay <file|dir>...
4	//!   zarrow-fuzz <target> run <N|Ns> --corpus <dir>... --out <dir> [--seed N] [--max-len N]
5	//!   zarrow-fuzz gen-seeds <corpus-root>
6	//!
7	//! Every decoded array goes through validateFull. A returned error is a pass; a panic, hang,
8	//! leak or allocation over the cap is a finding. The same `runOne` backs the std.testing.fuzz
9	//! tests at the bottom (`zig build fuzz-test --fuzz=100K`, Linux only).
10	const std = @import("std");
11	const zarrow = @import("zarrow");
12	
13	const Allocator = std.mem.Allocator;
14	const ArrayRef = zarrow.ArrayRef;
15	const DataType = zarrow.DataType;
16	const Field = zarrow.Field;
17	
18	pub const Target = enum {
19	    @"ipc-stream",
20	    @"ipc-stream-zero-copy",
21	    @"ipc-file",
22	    @"array-layout",
23	    compute,
24	    @"c-abi",
25	};
26	
27	/// Inputs over this size are skipped (replay) or never produced (run).
28	pub const max_input_len: usize = 1 << 20;
29	/// Live bytes one input may allocate before it counts as an OOM finding.
30	pub var alloc_cap: usize = 256 << 20;
31	/// Print the error return trace of a rejected input (set by single-file replay).
32	var explain = false;
33	const max_batches = 64;
34	/// In-memory corpus cap for `run`; past it, new signatures are still counted but not kept.
35	const max_corpus = 1 << 14;
36	
37	/// What one execution looked like; a new `sig` grows the corpus (our stand-in for coverage).
38	pub const Feedback = struct {
39	    err: ?anyerror = null,
40	    batches: u32 = 0,
41	    types: u64 = 0, // bit per decoded TypeId (mod 64), children included
42	    invalid: ?anyerror = null, // first validateFull error
43	
44	    fn sig(f: Feedback) u64 {
45	        var h = std.hash.Wyhash.init(0);
46	        h.update(if (f.err) |e| @errorName(e) else "ok");
47	        h.update(if (f.invalid) |e| @errorName(e) else "valid");
48	        h.update(std.mem.asBytes(&@min(f.batches, 8)));
49	        h.update(std.mem.asBytes(&f.types));
50	        return h.final();
51	    }
52	
53	    fn typeBits(data: *const zarrow.ArrayData) u64 {
54	        var bits = @as(u64, 1) << @intCast(@intFromEnum(data.data_type.id()) % 64);
55	        for (data.children) |child| bits |= typeBits(child.data());
56	        return bits;
57	    }
58	
59	    fn noteArray(f: *Feedback, arr: ArrayRef) bool {
60	        f.types |= typeBits(arr.data());
61	        arr.data().validateFull() catch |e| {
62	            if (f.invalid == null) f.invalid = e;
63	            return false;
64	        };
65	        return true;
66	    }
67	};
68	
69	// ---------------------------------------------------------------------------------------------
70	// Allocation cap + per-input leak check.
71	
72	const CountingAllocator = struct {
73	    parent: Allocator,
74	    live: usize = 0,
75	
76	    fn allocator(self: *CountingAllocator) Allocator {
77	        return .{ .ptr = self, .vtable = &.{ .alloc = alloc, .resize = resize, .remap = remap, .free = free } };
78	    }
79	
80	    fn charge(self: *CountingAllocator, old: usize, new: usize) void {
81	        if (new > old and self.live + (new - old) > alloc_cap)
82	            std.debug.panic("fuzz-oom: allocation of {d} bytes with {d} live exceeds cap {d}", .{ new - old, self.live, alloc_cap });
83	    }
84	
85	    fn alloc(ctx: *anyopaque, len: usize, a: std.mem.Alignment, ra: usize) ?[*]u8 {
86	        const self: *CountingAllocator = @ptrCast(@alignCast(ctx));
87	        self.charge(0, len);
88	        const p = self.parent.rawAlloc(len, a, ra) orelse return null;
89	        self.live += len;
90	        return p;
91	    }
92	
93	    fn resize(ctx: *anyopaque, m: []u8, a: std.mem.Alignment, n: usize, ra: usize) bool {
94	        const self: *CountingAllocator = @ptrCast(@alignCast(ctx));
95	        self.charge(m.len, n);
96	        if (!self.parent.rawResize(m, a, n, ra)) return false;
97	        self.live = self.live - m.len + n;
98	        return true;
99	    }
100	
101	    fn remap(ctx: *anyopaque, m: []u8, a: std.mem.Alignment, n: usize, ra: usize) ?[*]u8 {
102	        const self: *CountingAllocator = @ptrCast(@alignCast(ctx));
103	        self.charge(m.len, n);
104	        const p = self.parent.rawRemap(m, a, n, ra) orelse return null;
105	        self.live = self.live - m.len + n;
106	        return p;
107	    }
108	
109	    fn free(ctx: *anyopaque, m: []u8, a: std.mem.Alignment, ra: usize) void {
110	        const self: *CountingAllocator = @ptrCast(@alignCast(ctx));
111	        self.parent.rawFree(m, a, ra);
112	        self.live -= m.len;
113	    }
114	};
115	
116	/// Runs one input against `target`. Panics (= finding) on leaks, cap overruns and broken
117	/// invariants; library errors are returned in the feedback.
118	pub fn runOne(target: Target, parent: Allocator, bytes: []const u8) Feedback {
119	    var counting: CountingAllocator = .{ .parent = parent };
120	    const gpa = counting.allocator();
121	    var fb: Feedback = .{};
122	    const result = switch (target) {
123	        .@"ipc-stream" => ipcStream(gpa, bytes, false, &fb),
124	        .@"ipc-stream-zero-copy" => ipcStream(gpa, bytes, true, &fb),
125	        .@"ipc-file" => ipcFile(gpa, bytes, &fb),
126	        .compute => computeTarget(gpa, bytes, &fb),
127	        .@"array-layout" => arrayLayout(gpa, bytes, &fb),
128	        .@"c-abi" => cAbi(gpa, bytes, &fb),
129	    };
130	    result catch |e| {
131	        fb.err = e;
132	        // Single-file replay: show where the input was rejected (compat-gap triage).
133	        if (explain) if (@errorReturnTrace()) |trace| std.debug.dumpErrorReturnTrace(trace);
134	    };
135	    if (counting.live != 0) std.debug.panic("fuzz-leak: {d} bytes still allocated after the input", .{counting.live});
136	    return fb;
137	}
