139	// ---------------------------------------------------------------------------------------------
140	// IPC targets.
141	
142	fn noteBatch(fb: *Feedback, batch: *const zarrow.RecordBatch) void {
143	    fb.batches += 1;
144	    for (0..batch.numColumns()) |i| _ = fb.noteArray(batch.column(i).*);
145	}
146	
147	fn ipcStream(gpa: Allocator, bytes: []const u8, zero_copy: bool, fb: *Feedback) !void {
148	    const zc = zero_copy and bytes.len > 0;
149	    var source = zarrow.SharedBuffer.empty;
150	    if (zc) {
151	        var owned = try zarrow.OwnedBuffer.initUninit(gpa, bytes.len);
152	        @memcpy(owned.data[0..bytes.len], bytes);
153	        source = try owned.toShared(bytes.len);
154	    }
155	    defer source.release();
156	    var fixed: std.Io.Reader = .fixed(if (zc) source.data else bytes);
157	    var reader = if (zc) zarrow.IpcStreamReader.initZeroCopy(gpa, &fixed, source) else zarrow.IpcStreamReader.init(gpa, &fixed);
158	    defer reader.deinit();
159	
160	    _ = reader.readSchema() catch |e| {
161	        // Tensor streams have no schema message: walk them with the tensor API instead.
162	        var fixed2: std.Io.Reader = .fixed(bytes);
163	        var tensors = zarrow.IpcStreamReader.init(gpa, &fixed2);
164	        defer tensors.deinit();
165	        while (fb.batches < max_batches) {
166	            var msg = (tensors.nextTensorLikeMessage() catch break) orelse break;
167	            msg.deinit();
168	            fb.batches += 1;
169	        }
170	        return e;
171	    };
172	    while (fb.batches < max_batches) {
173	        var batch = (try reader.nextRecordBatch()) orelse return;
174	        defer batch.deinit();
175	        noteBatch(fb, &batch);
176	    }
177	}
178	
179	fn ipcFile(gpa: Allocator, bytes: []const u8, fb: *Feedback) !void {
180	    var reader = zarrow.IpcFileReader.init(gpa, bytes);
181	    defer reader.deinit();
182	    _ = try reader.readSchema();
183	    const n = try reader.recordBatchCount();
184	    for (0..@min(n, max_batches)) |i| {
185	        var batch = try reader.readRecordBatchAt(i);
186	        defer batch.deinit();
187	        noteBatch(fb, &batch);
188	    }
189	    for (0..@min(try reader.tensorCount(), max_batches)) |i| {
190	        var t = try reader.readTensorAt(i);
191	        t.deinit();
192	    }
193	    for (0..@min(try reader.sparseTensorCount(), max_batches)) |i| {
194	        var t = try reader.readSparseTensorAt(i);
195	        t.deinit();
196	    }
197	}
198	
199	fn computeTarget(gpa: Allocator, bytes: []const u8, fb: *Feedback) !void {
200	    var prng = std.Random.DefaultPrng.init(std.hash.Wyhash.hash(1, bytes));
201	    var fixed: std.Io.Reader = .fixed(bytes);
202	    var reader = zarrow.IpcStreamReader.init(gpa, &fixed);
203	    defer reader.deinit();
204	    _ = try reader.readSchema();
205	    while (fb.batches < max_batches) {
206	        var batch = (try reader.nextRecordBatch()) orelse return;
207	        defer batch.deinit();
208	        fb.batches += 1;
209	        for (0..batch.numColumns()) |i| {
210	            const col = batch.column(i).*;
211	            if (fb.noteArray(col)) try exerciseCompute(gpa, col, prng.random());
212	        }
213	    }
214	}
215	
216	/// slice/take/filter/concat on an array that passed validateFull; every output must validate
217	/// and have the expected length, otherwise the kernel broke an invariant (a finding).
218	fn exerciseCompute(gpa: Allocator, arr: ArrayRef, rng: std.Random) !void {
219	    const len = arr.data().length;
220	    const off = rng.uintAtMost(usize, len);
221	    const sub_len = rng.uintAtMost(usize, len - off);
222	    var sliced = try arr.slice(off, sub_len);
223	    defer sliced.release();
224	    expectValid("slice", sliced, sub_len);
225	
226	    var indices: [32]usize = undefined;
227	    const n_idx = if (len == 0) 0 else rng.uintAtMost(usize, indices.len);
228	    for (indices[0..n_idx]) |*ix| ix.* = rng.uintLessThan(usize, len);
229	    if (zarrow.computeDatumTake(.{ .array = arr }, indices[0..n_idx])) |taken| {
230	        var out = taken;
231	        defer out.release();
232	        if (out.asArray()) |a| expectValid("take", a, n_idx);
233	    } else |_| {}
234	
235	    var pred_builder = try zarrow.BooleanBuilder.init(gpa, len);
236	    defer pred_builder.deinit();
237	    var expected_rows: usize = 0;
238	    const drop_nulls = rng.boolean();
239	    for (0..len) |_| switch (rng.uintLessThan(u8, 3)) {
240	        0 => try pred_builder.append(false),
241	        1 => {
242	            try pred_builder.append(true);
243	            expected_rows += 1;
244	        },
245	        else => {
246	            try pred_builder.appendNull();
247	            if (!drop_nulls) expected_rows += 1;
248	        },
249	    };
250	    var pred = try pred_builder.finish();
251	    defer pred.release();
252	    if (zarrow.computeDatumFilter(.{ .array = arr }, .{ .array = pred }, .{ .drop_nulls = drop_nulls })) |filtered| {
253	        var out = filtered;
254	        defer out.release();
255	        if (out.asArray()) |a| expectValid("filter", a, expected_rows);
256	    } else |_| {}
257	
258	    if (zarrow.concatArrayRefs(gpa, arr.data().data_type, &.{ arr, sliced })) |joined| {
259	        var out = joined;
260	        defer out.release();
261	        expectValid("concat", out, len + sub_len);
262	    } else |_| {}
263	}
264	
265	fn expectValid(op: []const u8, arr: ArrayRef, expected_len: usize) void {
266	    arr.data().validateFull() catch |e| std.debug.panic("fuzz-invariant: {s} of a valid {s} array failed validateFull: {s}", .{ op, @tagName(arr.data().data_type.id()), @errorName(e) });
267	    if (arr.data().length != expected_len)
268	        std.debug.panic("fuzz-invariant: {s} returned {d} rows, expected {d}", .{ op, arr.data().length, expected_len });
269	}
