366	/// Child types the layout expects (what validateLayout checks children against).
367	fn childTypes(a: Allocator, dt: DataType) Allocator.Error![]const *const DataType {
368	    const one = struct {
369	        fn of(al: Allocator, t: *const DataType) Allocator.Error![]const *const DataType {
370	            const s = try al.alloc(*const DataType, 1);
371	            s[0] = t;
372	            return s;
373	        }
374	    }.of;
375	    return switch (dt) {
376	        .list, .large_list => |l| one(a, l.value_field.data_type),
377	        .list_view, .large_list_view => |l| one(a, l.value_field.data_type),
378	        .fixed_size_list => |l| one(a, l.value_field.data_type),
379	        .struct_ => |s| fieldTypes(a, s.fields),
380	        .sparse_union, .dense_union => |u| fieldTypes(a, u.fields),
381	        .map => |m| blk: {
382	            const fields = try a.alloc(Field, 2);
383	            fields[0] = m.key_field;
384	            fields[1] = m.item_field;
385	            const entries = try a.create(DataType);
386	            entries.* = .{ .struct_ = .{ .fields = fields } };
387	            break :blk one(a, entries);
388	        },
389	        .run_end_encoded => |r| blk: {
390	            const s = try a.alloc(*const DataType, 2);
391	            const ends = try a.create(DataType);
392	            ends.* = intDataType(r.run_end_type);
393	            s[0] = ends;
394	            s[1] = r.value_type;
395	            break :blk s;
396	        },
397	        .extension => |e| childTypes(a, e.storage_type.*),
398	        else => &.{},
399	    };
400	}
401	
402	fn fieldTypes(a: Allocator, fields: []const Field) Allocator.Error![]const *const DataType {
403	    const s = try a.alloc(*const DataType, fields.len);
404	    for (s, fields) |*t, f| t.* = f.data_type;
405	    return s;
406	}
407	
408	fn bufferCount(dt: DataType) usize {
409	    return switch (dt) {
410	        .null, .run_end_encoded => 0,
411	        .struct_, .fixed_size_list, .sparse_union => 1,
412	        .string, .binary, .large_string, .large_binary, .list_view, .large_list_view => 3,
413	        .string_view, .binary_view => 4,
414	        .extension => |e| bufferCount(e.storage_type.*),
415	        else => 2,
416	    };
417	}
418	
419	fn genBuffer(in: *Input, rng: std.Random, a: Allocator, total: usize) Allocator.Error!zarrow.SharedBuffer {
420	    const mode = in.byte() % 8;
421	    const n = switch (mode) {
422	        0 => return zarrow.SharedBuffer.empty,
423	        1 => in.below(257),
424	        else => (total + 1) * 32,
425	    };
426	    const buf = try a.alignedAlloc(u8, .fromByteUnits(64), n);
427	    switch (mode) {
428	        1 => rng.bytes(buf),
429	        2 => @memset(buf, 0),
430	        3 => @memset(buf, 0xff),
431	        4, 5 => { // ascending offsets / run ends (i32 or i64) with small steps
432	            const step = in.byte() % 4;
433	            var v: i64 = 0;
434	            if (mode == 4) {
435	                for (std.mem.bytesAsSlice(i32, buf)) |*x| {
436	                    x.* = @intCast(v);
437	                    v += rng.uintAtMost(u8, step);
438	                }
439	            } else for (std.mem.bytesAsSlice(i64, buf)) |*x| {
440	                x.* = v;
441	                v += rng.uintAtMost(u8, step);
442	            }
443	        },
444	        6 => for (buf) |*x| { // small ids (union type ids, dictionary indices)
445	            x.* = rng.uintLessThan(u8, 4);
446	        },
447	        else => rng.bytes(buf),
448	    }
449	    return zarrow.SharedBuffer.fromSlice(buf);
450	}
451	
452	fn genArray(in: *Input, rng: std.Random, a: Allocator, gpa: Allocator, dt: *const DataType, depth: u32) Allocator.Error!ArrayRef {
453	    const length = in.below(65);
454	    const offset = in.below(17);
455	    const total = length + offset;
456	    const null_count: ?usize = switch (in.byte() % 4) {
457	        0 => null,
458	        1 => 0,
459	        2 => length,
460	        else => in.below(70),
461	    };
462	    var n_buffers = bufferCount(dt.*);
463	    if (in.byte() % 8 == 0) n_buffers = in.below(5);
464	    const buffers = try a.alloc(zarrow.SharedBuffer, n_buffers);
465	    for (buffers) |*b| b.* = try genBuffer(in, rng, a, total);
466	
467	    var child_types = try childTypes(a, dt.*);
468	    if (in.byte() % 16 == 0) child_types = child_types[0 .. child_types.len - @min(child_types.len, 1)];
469	    const children = try a.alloc(ArrayRef, if (depth < 4) child_types.len else 0);
470	    var made: usize = 0;
471	    defer for (children[0..made]) |*c| c.release();
472	    for (children) |*c| {
473	        c.* = try genArray(in, rng, a, gpa, child_types[made], depth + 1);
474	        made += 1;
475	    }
476	    var dictionary: ?ArrayRef = null;
477	    defer if (dictionary) |*d| d.release();
478	    if (dt.* == .dictionary and depth < 4 and in.byte() % 8 != 0)
479	        dictionary = try genArray(in, rng, a, gpa, dt.dictionary.value_type, depth + 1);
480	
481	    return ArrayRef.fromBorrowed(gpa, .{
482	        .data_type = dt.*,
483	        .length = length,
484	        .offset = offset,
485	        .null_count = null_count,
486	        .buffers = buffers,
487	        .children = children,
488	        .dictionary = dictionary,
489	    });
490	}
491	
492	fn arrayLayout(gpa: Allocator, bytes: []const u8, fb: *Feedback) !void {
493	    var arena_state = std.heap.ArenaAllocator.init(gpa);
494	    defer arena_state.deinit();
495	    const a = arena_state.allocator();
496	    var prng = std.Random.DefaultPrng.init(std.hash.Wyhash.hash(2, bytes));
497	    var in: Input = .{ .bytes = bytes };
498	    const dt = try genType(&in, a, 0);
499	    var arr = try genArray(&in, prng.random(), a, gpa, dt, 0);
500	    defer arr.release();
501	    try arr.data().validateLayout();
502	    const valid = fb.noteArray(arr);
503	    // The type tree comes straight from the input: only the root type is a useful signal here.
504	    fb.types = @as(u64, 1) << @intCast(@intFromEnum(dt.id()) % 64);
505	    if (valid) try exerciseCompute(gpa, arr, prng.random());
506	}
