508	// ---------------------------------------------------------------------------------------------
509	// c-abi: ArrowSchema/ArrowArray trees built from bytes, imported through the C Data Interface.
510	//
511	// The C ABI trusts producer pointers and buffer sizes by contract, so every buffer points into
512	// one 64 KiB arena whose integers are all in 0..255 (or -1), and lengths stay below 256: any
513	// size the importer derives fits. Everything else (formats, counts, lengths, flags, metadata,
514	// tree shape) is fuzzed.
515	
516	const arena_len = 72 << 10;
517	
518	const formats = [_][]const u8{
519	    "n",    "b",       "c",          "C",   "s",   "S",   "i",    "I",    "l",   "L",   "e",   "f",   "g",
520	    "u",    "U",       "z",          "Z",   "vu",  "vz",  "tdD",  "tdm",  "tts", "ttm", "ttu", "ttn", "tDs",
521	    "tDm",  "tDu",     "tDn",        "tiM", "tiD", "tin", "+l",   "+L",   "+vl", "+vL", "+r",  "+m",  "+s",
522	    "tss:", "tsu:UTC", "tsn:+01:00", "w:",  "d:",  "+w:", "+us:", "+ud:",
523	};
524	
525	fn genFormat(in: *Input, a: Allocator, n_children: usize) Allocator.Error![:0]const u8 {
526	    const pick = in.byte() % (formats.len + 1);
527	    if (pick == formats.len) { // raw garbage
528	        const s = try a.allocSentinel(u8, in.below(9), 0);
529	        for (s) |*c| c.* = in.byte() | 1;
530	        return s;
531	    }
532	    const f = formats[pick];
533	    if (std.mem.eql(u8, f, "w:")) return std.fmt.allocPrintSentinel(a, "w:{d}", .{@as(i32, in.byte() % 66) - 1}, 0);
534	    if (std.mem.eql(u8, f, "+w:")) return std.fmt.allocPrintSentinel(a, "+w:{d}", .{@as(i32, @as(i8, @bitCast(in.byte())))}, 0);
535	    if (std.mem.eql(u8, f, "d:")) {
536	        const widths = [_]u32{ 32, 64, 128, 256, 0, 7 };
537	        return std.fmt.allocPrintSentinel(a, "d:{d},{d},{d}", .{ in.byte() % 80, @as(i8, @bitCast(in.byte())), widths[in.byte() % widths.len] }, 0);
538	    }
539	    if (std.mem.startsWith(u8, f, "+u")) {
540	        var list: std.ArrayList(u8) = .empty;
541	        try list.appendSlice(a, f);
542	        for (0..n_children) |i| {
543	            if (i > 0) try list.append(a, ',');
544	            const id: i32 = if (in.byte() % 4 == 0) @as(i8, @bitCast(in.byte())) else @intCast(i);
545	            try list.print(a, "{d}", .{id});
546	        }
547	        return list.toOwnedSliceSentinel(a, 0);
548	    }
549	    return a.dupeSentinel(u8, f, 0);
550	}
551	
552	fn expectedChildren(fmt: []const u8, in: *Input) usize {
553	    if (std.mem.eql(u8, fmt, "+r")) return 2;
554	    if (std.mem.eql(u8, fmt, "+s") or std.mem.startsWith(u8, fmt, "+u")) return in.below(4);
555	    if (fmt.len > 1 and fmt[0] == '+') return 1;
556	    return 0;
557	}
558	
559	fn expectedBuffers(fmt: []const u8) usize {
560	    if (std.mem.eql(u8, fmt, "n") or std.mem.eql(u8, fmt, "+r")) return 0;
561	    if (std.mem.eql(u8, fmt, "+s") or std.mem.startsWith(u8, fmt, "+w") or std.mem.startsWith(u8, fmt, "+us")) return 1;
562	    if (std.mem.eql(u8, fmt, "vu") or std.mem.eql(u8, fmt, "vz")) return 4;
563	    if (std.mem.eql(u8, fmt, "u") or std.mem.eql(u8, fmt, "U") or std.mem.eql(u8, fmt, "z") or
564	        std.mem.eql(u8, fmt, "Z") or std.mem.startsWith(u8, fmt, "+v")) return 3;
565	    return 2;
566	}
567	
568	fn releaseSchema(s: ?*zarrow.ArrowSchema) callconv(.c) void {
569	    s.?.release = null;
570	}
571	
572	fn releaseArray(arr: ?*zarrow.ArrowArray) callconv(.c) void {
573	    arr.?.release = null;
574	}
575	
576	fn genMetadata(in: *Input, a: Allocator) Allocator.Error![*c]const u8 {
577	    if (in.byte() % 4 != 0) return null;
578	    var blob: std.ArrayList(u8) = .empty;
579	    const keys = [_][]const u8{ "ARROW:extension:name", "ARROW:extension:metadata", "k", "" };
580	    const n = in.below(4);
581	    try blob.appendSlice(a, std.mem.asBytes(&std.mem.nativeToLittle(i32, @intCast(n))));
582	    for (0..n) |_| {
583	        const key = keys[in.byte() % keys.len];
584	        const value = in.bytes[@min(in.pos, in.bytes.len)..@min(in.pos + in.below(8), in.bytes.len)];
585	        try blob.appendSlice(a, std.mem.asBytes(&std.mem.nativeToLittle(i32, @intCast(key.len))));
586	        try blob.appendSlice(a, key);
587	        try blob.appendSlice(a, std.mem.asBytes(&std.mem.nativeToLittle(i32, @intCast(value.len))));
588	        try blob.appendSlice(a, value);
589	    }
590	    return blob.items.ptr;
591	}
592	
593	fn genCSchema(in: *Input, a: Allocator, depth: u32, root: bool) Allocator.Error!*zarrow.ArrowSchema {
594	    const s = try a.create(zarrow.ArrowSchema);
595	    var n_children: usize = 0;
596	    const fmt: [:0]const u8 = if (root and in.byte() % 16 != 0) "+s" else blk: {
597	        const pos = in.pos;
598	        const probe = try genFormat(in, a, 0);
599	        n_children = if (depth < 4) expectedChildren(probe, in) else 0;
600	        if (std.mem.startsWith(u8, probe, "+u")) { // regenerate with matching id count
601	            in.pos = pos;
602	            break :blk try genFormat(in, a, n_children);
603	        }
604	        break :blk probe;
605	    };
606	    if (root) n_children = in.below(4);
607	    if (in.byte() % 16 == 0) n_children = in.below(4);
608	    const children = try a.alloc(?*zarrow.ArrowSchema, n_children);
609	    for (children) |*c| c.* = try genCSchema(in, a, depth + 1, false);
610	    const is_int = fmt.len == 1 and std.mem.indexOfScalar(u8, "cCsSiIlL", fmt[0]) != null;
611	    s.* = .{
612	        .format = fmt.ptr,
613	        .name = if (in.byte() % 8 == 0) null else "f",
614	        .metadata = try genMetadata(in, a),
615	        .flags = switch (in.byte() % 4) {
616	            0 => 0,
617	            1 => 2,
618	            2 => in.byte() % 8,
619	            else => @as(i8, @bitCast(in.byte())),
620	        },
621	        .n_children = if (in.byte() % 32 == 0) -1 else @intCast(n_children),
622	        .children = children.ptr,
623	        .dictionary = if (is_int and depth < 4 and in.byte() % 4 == 0) try genCSchema(in, a, depth + 1, false) else null,
624	        .release = releaseSchema,
625	        .private_data = null,
626	    };
627	    return s;
628	}
629	
630	fn genCArray(in: *Input, a: Allocator, mem: []align(64) const u8, schema: *const zarrow.ArrowSchema) Allocator.Error!*zarrow.ArrowArray {
631	    const arr = try a.create(zarrow.ArrowArray);
632	    const fmt = std.mem.span(schema.format);
633	    var n_buffers = expectedBuffers(fmt);
634	    if (in.byte() % 8 == 0) n_buffers = in.below(6);
635	    const buffers = try a.alloc(?*const anyopaque, n_buffers);
636	    for (buffers) |*b| b.* = if (in.byte() % 32 == 0) null else @ptrCast(mem[64 * in.below(16) ..].ptr);
637	    const schema_children: usize = @intCast(@max(schema.n_children, 0));
638	    var n_children = schema_children;
639	    if (in.byte() % 16 == 0) n_children = in.below(4);
640	    const children = try a.alloc(?*zarrow.ArrowArray, n_children);
641	    for (children, 0..) |*c, i| c.* = if (i < schema_children)
642	        try genCArray(in, a, mem, schema.children[i].?)
643	    else
644	        try genCArray(in, a, mem, schema);
645	    const length: i64 = if (in.byte() % 32 == 0) -1 else @intCast(in.below(201));
646	    arr.* = .{
647	        .length = length,
648	        .null_count = switch (in.byte() % 4) {
649	            0 => -1,
650	            1 => 0,
651	            2 => length,
652	            else => @intCast(in.below(210)),
653	        },
654	        .offset = if (in.byte() % 32 == 0) -1 else @intCast(in.below(56)),
655	        .n_buffers = @intCast(n_buffers),
656	        .n_children = @intCast(n_children),
657	        .buffers = buffers.ptr,
658	        .children = children.ptr,
659	        .dictionary = if (schema.dictionary) |d| try genCArray(in, a, mem, d) else null,
660	        .release = releaseArray,
661	        .private_data = null,
662	    };
663	    return arr;
664	}
