666	fn cAbi(gpa: Allocator, bytes: []const u8, fb: *Feedback) !void {
667	    var arena_state = std.heap.ArenaAllocator.init(gpa);
668	    defer arena_state.deinit();
669	    const a = arena_state.allocator();
670	    var in: Input = .{ .bytes = bytes };
671	
672	    const mem = try a.alignedAlloc(u8, .fromByteUnits(64), arena_len);
673	    switch (if (bytes.len == 0) 1 else in.byte() % 3) {
674	        0 => for (mem, 0..) |*b, i| { // ints read at any width are 0..255
675	            b.* = if (i % 8 == 0) bytes[i / 8 % bytes.len] else 0;
676	        },
677	        1 => @memset(mem, 0),
678	        else => @memset(mem, 0xff), // all -1: must be rejected as negative
679	    }
680	
681	    const c_schema = try genCSchema(&in, a, 0, true);
682	    const c_array = try genCArray(&in, a, mem, c_schema);
683	    var schema = try zarrow.importSchemaFromC(gpa, c_schema);
684	    defer schema.deinit();
685	    const top: DataType = .{ .struct_ = .{ .fields = schema.schema.fields } };
686	    var arr = try zarrow.importArrayFromC(gpa, &top, c_array);
687	    defer arr.release();
688	    fb.batches = 1;
689	    if (!fb.noteArray(arr)) return;
690	    var prng = std.Random.DefaultPrng.init(std.hash.Wyhash.hash(3, bytes));
691	    try exerciseCompute(gpa, arr, prng.random());
692	
693	    // Round trip what we accepted: export must produce something import accepts again.
694	    var exported = try zarrow.exportArrayToC(gpa, arr);
695	    var again = zarrow.importArrayFromC(gpa, &top, &exported) catch |e|
696	        std.debug.panic("fuzz-invariant: re-import of an exported valid array failed: {s}", .{@errorName(e)});
697	    defer again.release();
698	    expectValid("c-abi round trip", again, arr.data().length);
699	    var exported_schema = try zarrow.exportSchemaToC(gpa, schema.schema);
700	    var schema_again = zarrow.importSchemaFromC(gpa, &exported_schema) catch |e|
701	        std.debug.panic("fuzz-invariant: re-import of an exported schema failed: {s}", .{@errorName(e)});
702	    schema_again.deinit();
703	}
