705	// ---------------------------------------------------------------------------------------------
706	// Mutation engine (libFuzzer-style mutators; corpus grows on new Feedback signatures).
707	
708	const tokens = [_][]const u8{
709	    "ARROW1",           "ARROW1\x00\x00",   "\xff\xff\xff\xff", "\xff\xff\xff\xff\x00\x00\x00\x00",
710	    "\x04\x00",         "\x03\x00",         "\x00\x00\x00\x00", "\x01\x00\x00\x00",
711	    "\x08\x00\x0c\x00", "\x0c\x00\x00\x00", "\x10\x00\x00\x00", "\x00\x00\x00\x00\x00\x00\x00\x00",
712	};
713	const interesting = [_]u64{ 0, 1, 2, 4, 8, 16, 32, 64, 127, 128, 255, 256, 0x7fff, 0x8000, 0xffff, 0x10000, 0x7fffffff, 0x80000000, 0xffffffff, 0x7fffffffffffffff, 0x8000000000000000, std.math.maxInt(u64) };
714	
715	fn mutate(rng: std.Random, gpa: Allocator, buf: *std.ArrayList(u8), corpus: []const []const u8, max_len: usize) !void {
716	    const rounds = 1 + rng.uintLessThan(usize, 5);
717	    for (0..rounds) |_| {
718	        const len = buf.items.len;
719	        switch (rng.uintLessThan(u8, 11)) {
720	            0 => if (len > 0) { // erase a range
721	                const at = rng.uintLessThan(usize, len);
722	                const n = 1 + rng.uintLessThan(usize, @min(len - at, 64));
723	                buf.replaceRangeAssumeCapacity(at, n, &.{});
724	            },
725	            1 => if (len < max_len) { // insert random bytes
726	                const at = rng.uintAtMost(usize, len);
727	                var tmp: [16]u8 = undefined;
728	                const n = 1 + rng.uintLessThan(usize, @min(tmp.len, max_len - len));
729	                rng.bytes(tmp[0..n]);
730	                try buf.insertSlice(gpa, at, tmp[0..n]);
731	            },
732	            2 => if (len > 0) { // flip a bit
733	                buf.items[rng.uintLessThan(usize, len)] ^= @as(u8, 1) << rng.int(u3);
734	            },
735	            3 => if (len > 0) { // random byte
736	                buf.items[rng.uintLessThan(usize, len)] = rng.int(u8);
737	            },
738	            4, 5 => if (len > 0) { // arithmetic / interesting value at width 1/2/4/8
739	                const width = @as(usize, 1) << rng.int(u2);
740	                if (len < width) continue;
741	                const at = rng.uintAtMost(usize, len - width);
742	                var v: u64 = 0;
743	                @memcpy(std.mem.asBytes(&v)[0..width], buf.items[at..][0..width]);
744	                v = if (rng.boolean())
745	                    interesting[rng.uintLessThan(usize, interesting.len)]
746	                else
747	                    v +% @as(u64, @bitCast(@as(i64, rng.intRangeAtMost(i8, -35, 35))));
748	                if (rng.boolean()) v = @byteSwap(v) >> @intCast(64 - 8 * width);
749	                @memcpy(buf.items[at..][0..width], std.mem.asBytes(&v)[0..width]);
750	            },
751	            6 => if (len > 1) { // copy a chunk over another place
752	                const from = rng.uintLessThan(usize, len);
753	                const to = rng.uintLessThan(usize, len);
754	                const n = 1 + rng.uintLessThan(usize, @min(len - @max(from, to), 128));
755	                std.mem.copyForwards(u8, buf.items[to..][0..n], buf.items[from..][0..n]);
756	            },
757	            7, 8 => { // dictionary token, overwrite or insert
758	                const tok = tokens[rng.uintLessThan(usize, tokens.len)];
759	                const at = rng.uintAtMost(usize, len);
760	                if (rng.boolean() and at + tok.len <= len) {
761	                    @memcpy(buf.items[at..][0..tok.len], tok);
762	                } else if (len + tok.len <= max_len) try buf.insertSlice(gpa, at, tok);
763	            },
764	            9 => if (corpus.len > 0) { // splice with another corpus entry
765	                const other = corpus[rng.uintLessThan(usize, corpus.len)];
766	                const cut = rng.uintAtMost(usize, len);
767	                const from = rng.uintAtMost(usize, other.len);
768	                buf.shrinkRetainingCapacity(cut);
769	                try buf.appendSlice(gpa, other[from..@min(other.len, from + (max_len - cut))]);
770	            },
771	            else => if (len > 0) { // repeat a byte
772	                const at = rng.uintLessThan(usize, len);
773	                const n = rng.uintLessThan(usize, @min(64, max_len - @min(max_len, len)) + 1);
774	                try buf.appendNTimes(gpa, buf.items[at], n);
775	            },
776	        }
777	    }
778	}
