780	fn hexName(bytes: []const u8) [16]u8 {
781	    var digest: [20]u8 = undefined;
782	    std.crypto.hash.Sha1.hash(bytes, &digest, .{});
783	    return std.fmt.bytesToHex(digest[0..8].*, .lower);
784	}
