786	// ---------------------------------------------------------------------------------------------
787	// CLI.
788	
789	/// Path of the input being replayed, printed by the panic handler so a crash names its file.
790	var current_path: []const u8 = "";
791	/// Executions so far; the watchdog calls a hang when it stops moving for `hang_seconds`.
792	var progress = std.atomic.Value(u64).init(0);
793	var hang_seconds: u64 = 10;
794	
795	fn watchdog(io: std.Io) void {
796	    var last = progress.load(.monotonic);
797	    var still: u64 = 0;
798	    while (true) {
799	        io.sleep(.fromNanoseconds(1_000_000_000), .awake) catch return;
800	        const now = progress.load(.monotonic);
801	        still = if (now == last) still + 1 else 0;
802	        last = now;
803	        if (still >= hang_seconds) {
804	            std.debug.print("fuzz-hang: one input ran for over {d}s: {s}\n", .{ hang_seconds, if (current_path.len > 0) current_path else "<out>/current.bin" });
805	            std.process.exit(77);
806	        }
807	    }
808	}
809	pub const panic = std.debug.FullPanic(struct {
810	    fn f(msg: []const u8, ra: ?usize) noreturn {
811	        if (current_path.len > 0) std.debug.print("fuzz: crashing input: {s}\n", .{current_path});
812	        std.debug.defaultPanic(msg, ra);
813	    }
814	}.f);
815	
816	fn usage() noreturn {
817	    std.debug.print(
818	        \\usage: zarrow-fuzz <target> replay <file|dir>...
819	        \\       zarrow-fuzz <target> run <iters|secs s> --corpus <dir>... --out <dir> [--seed N] [--max-len N] [--alloc-cap N] [--timeout S]
820	        \\       zarrow-fuzz gen-seeds <corpus-root>
821	        \\targets: ipc-stream ipc-stream-zero-copy ipc-file array-layout compute c-abi
822	        \\
823	    , .{});
824	    std.process.exit(2);
825	}
826	
827	pub fn main(init: std.process.Init) !void {
828	    const gpa = init.gpa;
829	    const io = init.io;
830	    const arena = init.arena.allocator();
831	    const argv = try init.minimal.args.toSlice(arena);
832	    var args: std.ArrayList([]const u8) = .empty;
833	    var i: usize = 0;
834	    while (i < argv.len) : (i += 1) {
835	        if (std.mem.eql(u8, argv[i], "--timeout") and i + 1 < argv.len) {
836	            i += 1;
837	            hang_seconds = std.fmt.parseInt(u64, argv[i], 10) catch usage();
838	        } else try args.append(arena, argv[i]);
839	    }
840	    if (args.items.len < 3) usage();
841	    if (std.mem.eql(u8, args.items[1], "gen-seeds")) return genSeeds(gpa, io, args.items[2]);
842	    const target = std.meta.stringToEnum(Target, args.items[1]) orelse usage();
843	    (try std.Thread.spawn(.{}, watchdog, .{io})).detach();
844	    if (std.mem.eql(u8, args.items[2], "replay")) return replay(gpa, io, target, args.items[3..]);
845	    if (std.mem.eql(u8, args.items[2], "run")) return run(gpa, io, target, args.items[3..]);
846	    usage();
847	}
848	
849	/// Files directly under `path` (or `path` itself), sorted for a stable order.
850	fn listInputs(a: Allocator, io: std.Io, path: []const u8, out: *std.ArrayList([]const u8)) !void {
851	    var dir = std.Io.Dir.cwd().openDir(io, path, .{ .iterate = true }) catch |e| switch (e) {
852	        error.NotDir => return out.append(a, path),
853	        else => return e,
854	    };
855	    defer dir.close(io);
856	    const start = out.items.len;
857	    var it = dir.iterate();
858	    while (try it.next(io)) |entry| {
859	        if (entry.kind != .file) continue;
860	        if (std.mem.endsWith(u8, entry.name, ".md") or std.mem.eql(u8, entry.name, "NOTICE")) continue;
861	        try out.append(a, try std.fs.path.join(a, &.{ path, entry.name }));
862	    }
863	    std.mem.sort([]const u8, out.items[start..], {}, struct {
864	        fn lt(_: void, x: []const u8, y: []const u8) bool {
865	            return std.mem.order(u8, x, y) == .lt;
866	        }
867	    }.lt);
868	}
869	
870	fn replay(gpa: Allocator, io: std.Io, target: Target, paths: []const []const u8) !void {
871	    var arena_state = std.heap.ArenaAllocator.init(gpa);
872	    defer arena_state.deinit();
873	    const a = arena_state.allocator();
874	    var files: std.ArrayList([]const u8) = .empty;
875	    for (paths) |p| try listInputs(a, io, p, &files);
876	    var ok: usize = 0;
877	    var errors: usize = 0;
878	    explain = files.items.len == 1;
879	    for (files.items) |path| {
880	        const bytes = std.Io.Dir.cwd().readFileAlloc(io, path, gpa, .limited(max_input_len)) catch |e| {
881	            std.debug.print("skip {s}: {s}\n", .{ path, @errorName(e) });
882	            continue;
883	        };
884	        defer gpa.free(bytes);
885	        current_path = path;
886	        const fb = runOne(target, gpa, bytes);
887	        _ = progress.fetchAdd(1, .monotonic);
888	        current_path = "";
889	        if (fb.err != null) errors += 1 else ok += 1;
890	        if (files.items.len == 1) std.debug.print("{s}: {s}, {d} batches, validateFull: {s}\n", .{
891	            path,
892	            if (fb.err) |e| @errorName(e) else "ok",
893	            fb.batches,
894	            if (fb.invalid) |e| @errorName(e) else "ok",
895	        });
896	    }
897	    std.debug.print("{s}: replayed {d} inputs ({d} decoded, {d} rejected), no crash\n", .{ @tagName(target), files.items.len, ok, errors });
898	}
899	
900	fn run(gpa: Allocator, io: std.Io, target: Target, args: []const []const u8) !void {
901	    var arena_state = std.heap.ArenaAllocator.init(gpa);
902	    defer arena_state.deinit();
903	    const a = arena_state.allocator();
904	    if (args.len < 1) usage();
905	    const budget = args[0];
906	    const by_time = std.mem.endsWith(u8, budget, "s");
907	    const limit = std.fmt.parseInt(u64, if (by_time) budget[0 .. budget.len - 1] else budget, 10) catch usage();
908	    var out_dir: ?[]const u8 = null;
909	    var seed: u64 = @truncate(@as(u96, @bitCast(std.Io.Timestamp.now(io, .real).toNanoseconds())));
910	    var max_len: usize = 64 << 10;
911	    var corpus_paths: std.ArrayList([]const u8) = .empty;
912	    var i: usize = 1;
913	    while (i + 1 < args.len) : (i += 2) {
914	        const v = args[i + 1];
915	        if (std.mem.eql(u8, args[i], "--corpus")) {
916	            listInputs(a, io, v, &corpus_paths) catch |e| std.debug.print("corpus {s}: {s}\n", .{ v, @errorName(e) });
917	        } else if (std.mem.eql(u8, args[i], "--out")) {
918	            out_dir = v;
919	        } else if (std.mem.eql(u8, args[i], "--seed")) {
920	            seed = std.fmt.parseInt(u64, v, 10) catch usage();
921	        } else if (std.mem.eql(u8, args[i], "--max-len")) {
922	            max_len = @min(std.fmt.parseInt(usize, v, 10) catch usage(), max_input_len);
923	        } else if (std.mem.eql(u8, args[i], "--alloc-cap")) {
924	            alloc_cap = std.fmt.parseInt(usize, v, 10) catch usage();
925	        } else usage();
926	    }
927	    const out = out_dir orelse usage();
928	    const cwd = std.Io.Dir.cwd();
929	    const grow_dir = try std.fs.path.join(a, &.{ out, "corpus" });
930	    try cwd.createDirPath(io, grow_dir);
931	    try listInputs(a, io, grow_dir, &corpus_paths);
932	    const current = try cwd.createFile(io, try std.fs.path.join(a, &.{ out, "current.bin" }), .{ .truncate = true });
933	    defer current.close(io);
934	    var out_handle = try cwd.openDir(io, out, .{});
935	    defer out_handle.close(io);
936	
937	    // Load the corpus, skipping inputs that crashed before (tools/fuzz.py marks <out>/skip/<hash>).
938	    var corpus: std.ArrayList([]const u8) = .empty;
939	    var seen: std.AutoHashMapUnmanaged(u64, void) = .empty;
940	    for (corpus_paths.items) |path| {
941	        const bytes = cwd.readFileAlloc(io, path, a, .limited(max_len)) catch continue;
942	        const hex = hexName(bytes);
943	        const crash_name = try std.fmt.allocPrint(a, "skip/{s}", .{&hex});
944	        if (out_handle.statFile(io, crash_name, .{})) |_| {
945	            std.debug.print("skipping known crasher {s}\n", .{path});
946	            continue;
947	        } else |_| {}
948	        try current.writePositionalAll(io, bytes, 0);
949	        try current.setLength(io, bytes.len);
950	        const fb = runOne(target, gpa, bytes);
951	        _ = progress.fetchAdd(1, .monotonic);
952	        try seen.put(a, fb.sig(), {});
953	        try corpus.append(a, bytes);
954	    }
955	    if (corpus.items.len == 0) try corpus.append(a, "");
956	    std.debug.print("{s}: seed {d}, {d} corpus inputs, {d} signatures\n", .{ @tagName(target), seed, corpus.items.len, seen.count() });
957	
958	    var prng = std.Random.DefaultPrng.init(seed);
959	    const rng = prng.random();
960	    var buf: std.ArrayList(u8) = .empty;
961	    defer buf.deinit(gpa);
962	    const start = std.Io.Timestamp.now(io, .awake);
963	    var iters: u64 = 0;
964	    while (true) : (iters += 1) {
965	        if (iters % 256 == 0) {
966	            const elapsed: u64 = @intCast(start.durationTo(std.Io.Timestamp.now(io, .awake)).toSeconds());
967	            if ((by_time and elapsed >= limit) or (!by_time and iters >= limit)) break;
968	            if (iters % (1 << 14) == 0 and iters > 0)
969	                std.debug.print("#{d} {d}s corpus {d} signatures {d}\n", .{ iters, elapsed, corpus.items.len, seen.count() });
970	        } else if (!by_time and iters >= limit) break;
971	
972	        buf.clearRetainingCapacity();
973	        try buf.appendSlice(gpa, corpus.items[rng.uintLessThan(usize, corpus.items.len)]);
974	        try mutate(rng, gpa, &buf, corpus.items, max_len);
975	        try current.writePositionalAll(io, buf.items, 0);
976	        try current.setLength(io, buf.items.len);
977	        const fb = runOne(target, gpa, buf.items);
978	        _ = progress.fetchAdd(1, .monotonic);
979	        const gop = try seen.getOrPut(a, fb.sig());
980	        // ponytail: fixed corpus cap; signature-based growth has no coverage to prune with.
981	        if (gop.found_existing or corpus.items.len >= max_corpus) continue;
982	        const copy = try a.dupe(u8, buf.items);
983	        try corpus.append(a, copy);
984	        const hex = hexName(copy);
985	        const name = try std.fmt.allocPrint(a, "{s}.bin", .{&hex});
986	        var dir = try cwd.openDir(io, grow_dir, .{});
987	        defer dir.close(io);
988	        try dir.writeFile(io, .{ .sub_path = name, .data = copy });
989	    }
990	    std.debug.print("{s}: done, {d} execs, corpus {d}, {d} signatures\n", .{ @tagName(target), iters, corpus.items.len, seen.count() });
991	}
992	
993	// ---------------------------------------------------------------------------------------------
994	// Seed generation: re-encode every decodable IPC stream in <root>/ipc-stream with zarrow's own
995	// writers (plain, lz4, zstd; stream and file; plus a sliced copy of each batch) so mutations
996	// start from rich, zarrow-produced inputs for every type the readers support.
997	
998	fn genSeeds(gpa: Allocator, io: std.Io, root: []const u8) !void {
999	    var arena_state = std.heap.ArenaAllocator.init(gpa);
1000	    defer arena_state.deinit();
1001	    const a = arena_state.allocator();
1002	    const cwd = std.Io.Dir.cwd();
1003	    const stream_dir = try std.fs.path.join(a, &.{ root, "ipc-stream" });
1004	    const file_dir = try std.fs.path.join(a, &.{ root, "ipc-file" });
1005	    try cwd.createDirPath(io, file_dir);
1006	    var inputs: std.ArrayList([]const u8) = .empty;
1007	    try listInputs(a, io, stream_dir, &inputs);
1008	    var written: usize = 0;
1009	    for (inputs.items) |path| {
1010	        // Only valid sources: skip earlier output and crash reproducers.
1011	        const base = std.fs.path.basename(path);
1012	        if (for ([_][]const u8{ "gen-", "regress-", "at-stream-", "at-tensor-" }) |p| {
1013	            if (std.mem.startsWith(u8, base, p)) break true;
1014	        } else false) continue;
1015	        const bytes = cwd.readFileAlloc(io, path, a, .limited(max_input_len)) catch continue;
1016	        if (runOne(.@"ipc-stream", gpa, bytes).err != null) continue;
1017	        for ([_]?zarrow.IpcBodyCompressionCodec{ null, .lz4_frame, .zstd }) |codec| {
1018	            for ([_]bool{ false, true }) |as_file| {
1019	                const encoded = (if (as_file) transcode(gpa, bytes, codec, true) else transcode(gpa, bytes, codec, false)) catch continue;
1020	                defer gpa.free(encoded);
1021	                const check: Target = if (as_file) .@"ipc-file" else .@"ipc-stream";
1022	                if (runOne(check, gpa, encoded).err != null or encoded.len > 16 << 10) continue;
1023	                const hex = hexName(encoded);
1024	                const name = try std.fmt.allocPrint(a, "{s}/gen-{s}-{s}.bin", .{
1025	                    if (as_file) file_dir else stream_dir,
1026	                    if (codec) |c| @tagName(c) else "plain",
1027	                    hex[0..12],
1028	                });
1029	                try cwd.writeFile(io, .{ .sub_path = name, .data = encoded });
1030	                written += 1;
1031	            }
1032	        }
1033	    }
1034	    std.debug.print("gen-seeds: wrote {d} seeds from {d} inputs\n", .{ written, inputs.items.len });
1035	}
1036	
1037	fn transcode(gpa: Allocator, bytes: []const u8, codec: ?zarrow.IpcBodyCompressionCodec, comptime as_file: bool) ![]u8 {
1038	    var fixed: std.Io.Reader = .fixed(bytes);
1039	    var reader = zarrow.IpcStreamReader.init(gpa, &fixed);
1040	    defer reader.deinit();
1041	    const schema = try reader.readSchema();
1042	    var out: std.Io.Writer.Allocating = .init(gpa);
1043	    errdefer out.deinit();
1044	    const options: zarrow.IpcStreamWriterOptions = .{ .body_compression = codec };
1045	    var writer = if (as_file)
1046	        try zarrow.IpcFileWriter.initWithOptions(gpa, &out.writer, options)
1047	    else
1048	        zarrow.IpcStreamWriter.initWithOptions(gpa, &out.writer, options);
1049	    defer writer.deinit();
1050	    try writer.writeSchema(schema);
1051	    while (try reader.nextRecordBatch()) |batch_value| {
1052	        var batch = batch_value;
1053	        defer batch.deinit();
1054	        try writer.writeRecordBatch(batch);
1055	        if (batch.numRows() > 2 and !as_file) { // sliced batches exercise non-zero offsets
1056	            var sliced = try batch.slice(1, batch.numRows() - 2);
1057	            defer sliced.deinit();
1058	            try writer.writeRecordBatch(sliced);
1059	        }
1060	    }
1061	    try writer.writeEnd();
1062	    return out.toOwnedSlice();
1063	}
1064	
1065	// ---------------------------------------------------------------------------------------------
1066	// std.testing.fuzz entry points: `zig build fuzz-test --fuzz=100K` (coverage-guided, Linux).
1067	// Under plain `zig build test` each runs once on its embedded seed and on empty input.
1068	
1069	fn smithSeed(comptime path: []const u8) []const u8 {
1070	    const data = @embedFile(path);
1071	    return comptime &(std.mem.toBytes(std.mem.nativeToLittle(u32, data.len)) ++ data.*);
1072	}
1073	
1074	fn fuzzOne(target: Target, smith: *std.testing.Smith) anyerror!void {
1075	    const S = struct {
1076	        var buf: [64 << 10]u8 = undefined;
1077	    };
1078	    const n = smith.slice(&S.buf);
1079	    _ = runOne(target, std.testing.allocator, S.buf[0..n]);
1080	}
1081	
1082	test "fuzz ipc-stream" {
1083	    try std.testing.fuzz(Target.@"ipc-stream", fuzzOne, .{ .corpus = &.{smithSeed("corpus/ipc-stream/zarrow-canonical.bin")} });
1084	}
1085	
1086	test "fuzz ipc-stream-zero-copy" {
1087	    try std.testing.fuzz(Target.@"ipc-stream-zero-copy", fuzzOne, .{ .corpus = &.{smithSeed("corpus/ipc-stream/zarrow-canonical.bin")} });
1088	}
1089	
1090	test "fuzz ipc-file" {
1091	    try std.testing.fuzz(Target.@"ipc-file", fuzzOne, .{ .corpus = &.{smithSeed("corpus/ipc-file/zarrow-canonical.bin")} });
1092	}
1093	
1094	test "fuzz compute" {
1095	    try std.testing.fuzz(Target.compute, fuzzOne, .{ .corpus = &.{smithSeed("corpus/ipc-stream/zarrow-canonical.bin")} });
1096	}
1097	
1098	test "fuzz array-layout" {
1099	    try std.testing.fuzz(Target.@"array-layout", fuzzOne, .{});
1100	}
1101	
1102	test "fuzz c-abi" {
1103	    try std.testing.fuzz(Target.@"c-abi", fuzzOne, .{});
1104	}
